def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    def opp_defects_run(k):
        run = 0
        i = n - 1
        while i >= 0 and opp[i] == 'D' and run < k:
            run += 1
            i -= 1
        return run

    def my_defects_run(k):
        run = 0
        i = n - 1
        while i >= 0 and me[i] == 'D' and run < k:
            run += 1
            i -= 1
        return run

    # Endgame exploitation: with DC=5 > CC=3, defect very late when safe.
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        if opp[-1] == 'D' or (n >= 5 and opp[-5:].count('D') >= 2):
            return 'D'
        return 'C'

    # Detect pure/very-heavy defectors and punish.
    if n >= 8:
        total_opp_d = opp.count('D')
        if total_opp_d >= n - 1:
            return 'D'
        if n >= 20 and total_opp_d >= int(0.85 * n):
            return 'D'
    else:
        total_opp_d = opp.count('D')

    # If opponent has been perfectly/very cooperative, keep cooperating with rare probing.
    if n >= 6:
        total_opp_d = opp.count('D')
        if total_opp_d == 0:
            if remaining <= 5:
                return 'D'
            if n >= 12 and n % 11 == 0:
                return 'D'
            return 'C'
        if n >= 10:
            ratio = total_opp_d / n
            if ratio < 0.08:
                return 'C'

    # Punish sustained defection.
    if n >= 4:
        recent = opp[-4:]
        if recent.count('D') >= 3:
            if n >= 8 and opp[-8:].count('D') >= 6:
                return 'D'
            if rng.random() < 0.85:
                return 'D'
            return 'C'

    if n >= 3 and opp[-3:] == ['D', 'D', 'D']:
        return 'D'

    # React to a defection: retaliate, but try to break retaliation cycles.
    if n >= 2 and opp[-1] == 'D':
        # If my last was D and their last D, offer a conciliatory C to break loops.
        if me[-1] == 'D' and opp_defects_run(2) == 1:
            # fresh isolated defection after my punishment: forgive
            return 'C' if rng.random() < 0.6 else 'D'
        if n >= 4 and opp[-4:].count('D') >= 2:
            return 'D'
        return 'D' if rng.random() < 0.75 else 'C'

    # Opponent just cooperated after I defected: reward with C.
    if n >= 2 and opp[-1] == 'C' and me[-1] == 'D':
        return 'C'

    # Longer-horizon ratio checks.
    if n >= 10:
        total_opp_d = opp.count('D')
        ratio = total_opp_d / n
        if ratio > 0.45:
            if rng.random() < 0.8:
                return 'D'
            return 'C'

    if n >= 6:
        last6 = opp[-6:]
        d6 = last6.count('D')
        if d6 == 1:
            return 'C'
        if d6 >= 3:
            return 'D'
        if d6 == 2:
            # temper with forgiveness
            if me[-1] == 'C' and opp[-1] == 'C':
                return 'C'
            if rng.random() < 0.4:
                return 'C'
            return 'D'

    # Pattern: single D isolated among C's - likely noise or probe; forgive.
    if n >= 5 and opp[-5:] == ['C', 'C', 'D', 'C', 'C']:
        return 'C'

    # Default: cooperate, preserving mutual cooperation.
    return 'C'
